SELECT Имена_станций.NAME, Имена_ОЭС.abbr AS oesname, Имена_областей.NAME AS oblname, Имена_станций.ordnumb, Станции2010.YEAR, Станции2010.NUST, Станции2010.nr, Станции2010.E, Станции2010.EOTP, Станции2010.EURT, Станции2010.EUST, Станции2010.Q, Станции2010.TURT, Станции2010.TUST, Станции2010.B, Станции2010.GAZ, Доп_угли2010.gazpp, Станции2010.MAZUT, Станции2010.TORF, Станции2010.SLAN, Станции2010.PROCH, Станции2010.UGOL, Станции2010.DON, Станции2010.PODM, Станции2010.PECH, Доп_угли2010.intin, Доп_угли2010.vork, Станции2010.ARKT, Станции2010.KUZN, Доп_угли2010.kuzngd, Доп_угли2010.kuznt, Доп_угли2010.kuznss, Доп_угли2010.kuznun, Станции2010.URAL, Доп_угли2010.sver, Доп_угли2010.chel, Доп_угли2010.kizel, Станции2010.BASHK, Станции2010.KAZAH, Доп_угли2010.ekib, Доп_угли2010.maikub, Станции2010.KARAG, Станции2010.KAN, Доп_угли2010.nazar, Доп_угли2010.ibor, Доп_угли2010.berez, Доп_угли2010.per, Доп_угли2010.irbei, Доп_угли2010.kansk, Станции2010.TUNG, Доп_угли2010.jer, Доп_угли2010.karab, Станции2010.IRKUT, Доп_угли2010.azey, Доп_угли2010.mug, Доп_угли2010.cher, Станции2010.HAK, Станции2010.TUV, Станции2010.BUR, Доп_угли2010.gusin, Доп_угли2010.tugn, Доп_угли2010.okino, Станции2010.CHIT, Доп_угли2010.har, Доп_угли2010.urt, Доп_угли2010.tataur, Доп_угли2010.tarbag, Доп_угли2010.zab_kam, Станции2010.YAKUT, Доп_угли2010.neru, Доп_угли2010.zyryan, Доп_угли2010.pyak, Станции2010.AMUR, Доп_угли2010.rai, Доп_угли2010.erk, Станции2010.URG, Станции2010.USHUM, Станции2010.PRIM, Доп_угли2010.bikin, Доп_угли2010.razdol, Доп_угли2010.hankai, Станции2010.MAG, Станции2010.SAH, Станции2010.KAMCH, Станции2010.CHUKOT, Доп_угли2010.anad, Доп_угли2010.bering, Станции2010.QOTR, Станции2010.SNK, Станции2010.EWTP, Станции2010.NT, Станции2010.OBOR, Станции2010.VED, Станции2010.OBL, Станции2010.DEP, Станции2010.OES, Станции2010.ER, Станции2010.NUMB1120, Имена_станций.Ведомство AS вед, IIf([ved]=1 Or [ved]=4,1,IIf([ved]=2 Or [ved]=3,2,0)) AS кэстэц, Имена_станций.D, Имена_станций.R, IIf([ved]>0,0,1) AS sost, IIf([main]>0,1,0) AS [group], Имена_станций.FO, Имена_станций.форэм, Имена_станций.GK, Станции2010.BE, имена_ГК.name AS namegk, имена_БЕ.name AS namebe, Города.Name AS Town, IIf([obor]=20 Or [obor]=90,"ГТУ",IIf([obor]=21 Or [obor]=91,"ПГУ",IIf([obor]=22,"Диз",IIf([obor]=23,"Дет","ПСУ")))) AS тип
FROM (((Имена_станций LEFT JOIN Города ON Имена_станций.codegor=Города.code) INNER JOIN (Имена_областей INNER JOIN (Имена_ОЭС INNER JOIN (Станции2010 LEFT JOIN Доп_угли2010 ON (Станции2010.NUMB1120=Доп_угли2010.NUMB1120) AND (Станции2010.YEAR=Доп_угли2010.YEAR)) ON Имена_ОЭС.oes=Станции2010.OES) ON Имена_областей.OBL=Станции2010.OBL) ON Имена_станций.NUMB=Станции2010.NUMB1120) LEFT JOIN имена_ГК ON Станции2010.GK=имена_ГК.code) LEFT JOIN имена_БЕ ON Станции2010.BE=имена_БЕ.code;
